const input = $json;
const groupName = String(input.group_name || 'L1-INFO-A');
const changeType = String(input.type || 'update');
const course = String(input.course_name || 'Cours');

const recipients = [
  { email: 'student1@demo.local', first_name: 'Alice' },
  { email: 'student2@demo.local', first_name: 'Bob' }
];

const out = recipients.map((s) => {
  let body = `Bonjour ${s.first_name},\n\n`;
  if (changeType === 'cancellation') {
    body += `Le cours ${course} est annulé.`;
  } else if (changeType === 'room_change') {
    body += `Le cours ${course} a changé de salle.`;
  } else {
    body += `Un changement a été effectué pour ${course}.`;
  }
  body += `\n\nGroupe: ${groupName}\n\nService scolarité`;

  return {
    json: {
      to: s.email,
      subject: `Changement d'emploi du temps - ${course}`,
      body,
      status: 'prepared'
    }
  };
});

return out;
